b:if.b:template-skin:
/*------Layout (No Edit)----------*/

body#layout #outer-wrapper,body#layout .row{
    width:auto;
    padding:0
}
body#layout{
    width:1240;
    position:relative;
    padding:95px 5px 0;
    margin:0
}
body#layout div.section{
    margin:0 5px 10px!important;
    padding:16px 16px 18px!important
}

body#layout .section h4{
    font-size:14px;
    margin:0
}
 body#layout .layout-widget-description{
    display:none
}
#layout div.section {
    background-color: #f8f8f8;
    border: 1px solid #ccc;
    font-family: Roboto, sans-serif;
    margin: 0 4px 8px 4px;
    overflow: visible;
    padding: 16px;
    position: relative;
}
 body#layout .theme-options,body#layout #main-menu .widget{
    display:block!important
}
 body#layout div.solar-panel{
    background-color:#d7d7d7!important;
    overflow:hidden!important;
    border-color:#bcbcbc
}
 body#layout .solar-panel .widget{
    float:left;
    width:49%;
    margin-right:2%
}
 body#layout .solar-panel #LinkList71{
    margin-right:0
}
 body#layout #top-bar{
    height:auto
}
 body#layout #top-bar .container{
    display:flex
}
 body#layout .top-bar-nav,body#layout .top-bar-social{
    width:50%
}
body#layout #slider-section .widget {
    display: block;
}
 body#layout #header-wrap{
    height:auto
}
 body#layout .header-header{
    float:left;
    width:100%;
    height:auto;
    padding:0
}
 body#layout .header-header .container{
    display:flex
}
 body#layout div.header-logo,body#layout div.header-ads{
    float:left;
    width:100%;
    height:auto;
    max-width:none;
    max-height:none
}
 body#layout #bottom-info {
  display:none;
}

 body#layout .header-ads .widget-content{
    width:auto
}
 body#layout .header-ads .add_widget{
    padding:15px!important
}
 body#layout .mobile-header{
    display:block;
    float:right;
    width:33.33%;
    height:auto
}
 body#layout .mobile-menu{
    display:none
}
 body#layout .header-menu{
    float:left;
    width:100%;
    height:auto
}
 body#layout #main-menu{
    width:94%;
    box-sizing:border-box;
    height:auto
}
 body#layout #hot-wrapper .widget{
    display:block
}
 body#layout #content-wrapper{
    margin:0
}
 body#layout #content-wrapper > .container{
    display:flex;
    margin:0
}
 body#layout #main-wrapper{
    min-width:66.66%;
    padding:0
}
 body#layout #sidebar-wrapper{
    width:33.33%;
    padding:0;
display:block;
}
 body#layout .sidebar .widget,body#layout .sidebar .widget-content{
    float:none;
    overflow:visible
}
 body#layout .footer-widgets-wrap{
    display:flex
}
 body#layout .footer-widgets-wrap div.footer{
    width:100%
}



/*------Layout (end)----------*/

head.script:
//
// Global variables with content. "Available for Edit"
var monthFormat = ["Nachexen", "Jahrdrung", "Pflugzeit", "Sigmarzeit", "Sommerzeit", "Vorgeheim", "Nachgeheim", "Erntezeit", "Brauzeit", "Kaldezeit", "Ulriczeit", "Vorhexen"],
    noThumbnail = "https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgP9LwUN5tSMplaxEkexsg1NpAOhCVAjcGOwUEhcgl4krjveZ060U-AnncTxuP851_yIYge97jVkqPLI9daavBdeMGfeYqDdPXpEzgvzwLsZKgIMoFxUFWJCojWMX_56XewbJjas0opBNs/w680/nth.png",
    postPerPage = 5,
    fixedSidebar = true,
    commentsSystem = "blogger";
