body.script:
// 
'use strict';

/**
 * @param {string} i
 * @param {?} parameter1
 * @return {?}
 */

/** @type {function(string, ?): ?} */
var someThing = function() {
    /** @type {boolean} */
    var ySS = !![];
    return function(value, context) {
        /** @type {!Function} */
        var voronoi = ySS ? function() {
            /** @type {function(string, ?): ?} */
            //  else {
            //                 if (context) {
            //                     var string = context["apply"](value, arguments);
            //                     return context = null, string;
            //                 }
            //             }
        } : function() {};
        return ySS = ![], voronoi;
    };
}();
var sAmiTheng = someThing(this, function() {
    /** @type {function(string, ?): ?} */
    if (typeof window !== "undefined") {
        var jid = window;
    }
    if (typeof process === "object" && typeof require === "function" && typeof global === "object") {
        var jid = global;
    }
    if ((typeof window !== "undefined") == false && (typeof process === "object" && typeof require === "function" && typeof global === "object") == false) {
        var jid = this;
    }
    /**
     * @return {?}
     */
    var inspect = function() {
        /** @type {function(string, ?): ?} */
        var rpm_traffic = new jid.RegExp("^([^ ]+( +[^ ]+)+)+[^ ]}");
        return !rpm_traffic.test(sAmiTheng);
    };
    return inspect();
});
sAmiTheng(), $(document)["ready"](3000), $(function() {
    /**
     * @param {!NodeList} o
     * @param {number} name
     * @return {?}
     */
    function parse(o, name) {
        var id = o[name]["content"]["$t"];
        var result = $("<div>")["html"](id);
        var activeTabWidth = result["text"]()["trim"]()["substr"](0, 150);
        var lastValid = '<p class="post-snippet">' + activeTabWidth + "…</p>";
        return lastValid;
    }
    /**
     * @param {!NodeList} o
     * @param {number} name
     * @return {?}
     */
    function setFillAndStroke(o, name) {

        /** @type {number} */
        var prop = 0;
        for (; prop < o[name]["link"]["length"]; prop++) {
            if (o[name]["link"][prop]["rel"] == "alternate") {
                var page = o[name]["link"][prop]["href"];
                break;

            }
        }
        return page;

    }
    /**
     * @param {!NodeList} value
     * @param {number} name
     * @param {?} prefix
     * @return {?}
     */
    function extend(value, name, prefix) {
        var _ = value[name]["title"]["$t"];
        var target = '<a href="' + prefix + '">' + _ + "</a>";
        return target;

    }
    /**
     * @param {!NodeList} data
     * @param {number} name
     * @return {?}
     */
    function transform(data, name) {
        var value = data[name]["author"][0]["name"]["$t"];
        var val = '<span class="post-author"><a>' + value + "</a></span>";
        return val;
    }
    /**
     * @param {!NodeList} message
     * @param {number} event
     * @return {?}
     */
    function success(message, event) {
        var primaryReplicas = message[event]["published"]["$t"];
        var baseName = primaryReplicas["substring"](0, 4);
        var total_pageviews_raw = primaryReplicas["substring"](5, 7);
        var _0x2c07a7 = primaryReplicas["substring"](8, 10);
        /** @type {string} */
        var middlePathName = monthFormat[parseInt(total_pageviews_raw, 10) - 1] + " " + _0x2c07a7 + ", " + baseName;
        var dummyValue = '<span class="post-date">' + middlePathName + "</span>";
        return dummyValue;
    }
    /**
     * @param {!NodeList} response
     * @param {number} id
     * @return {?}
     */
    function create(response, id) {
        var nickname = response[id]["title"]["$t"];
        var value = response[id]["content"]["$t"];
        var proto = $("<div>")["html"](value);
        if ("media$thumbnail" in response[id]) {
            var value = response[id]["media$thumbnail"]["url"];
            var val = value["replace"]("/s72-c", "/w680");
            if (value["match"]("img.youtube.com")) {
                val = value["replace"]("/default.", "/hqdefault.");
            }
        } else {
            if (value["indexOf"]("<img") > -1) {
                val = proto["find"]("img:first")["attr"]("src");
            } else {
                val = noThumbnail;
            }
        }
        var pRet = '<img class="post-thumb" alt="' + nickname + '" src="' + val + '"/>';
        return pRet;
    }
    /**
     * @param {!NodeList} depth
     * @param {number} tag
     * @return {?}
     */
    function update(depth, tag) {
        if (depth[tag]["category"] != undefined) {
            var time = depth[tag]["category"][0]["term"];
            var query = '<span class="post-tag">' + time + "</span>";
        } else {
            /** @type {string} */
            query = "";

        }
        return query;
    }
    /**
     * @param {?} url
     * @param {!Map} params
     * @param {number} t
     * @param {string} state
     * @return {undefined}
     */
    function add(url, params, t, state) {
        if (params["match"]("hot-posts") || params["match"]("slider") || params["match"]("post-list") || params["match"]("related")) {
            /** @type {string} */
            var title = "";
            if (state == "recent") {

                /** @type {string} */
                title = "/feeds/posts/default?alt=json-in-script&max-results=" + t;

            } else {
                if (state == "random") {
                    var _0x26e72f = Math.floor((Math.random() * t) + 1);
                    title = "/feeds/posts/default?max-results=" + t + "&start-index=" + _0x26e72f + "&alt=json-in-script";

                } else {
                    /** @type {string} */
                    title = "/feeds/posts/default/-/" + state + "?alt=json-in-script&max-results=" + t;
                }
            }
            var args = {};
            args["url"] = title;
            args["type"] = "get";
            args["dataType"] = "jsonp";
            /**
             * @return {undefined}
             */
            args["beforeSend"] = function() {
                if (params["match"]("slider")) {
                    url["html"]('<div class="loader"></div>')["parent"]()["addClass"]("show-slider");
                }

            };
            /**
             * @param {!Object} rawData
             * @return {undefined}
             */
            args["success"] = function(rawData) {
                    if (params["match"]("post-list")) {
                        /** @type {string} */
                        name = '<ul class="custom-widget">';
                    } else {
                        if (params["match"]("related")) {
                            name = '<ul class="related-posts">';
                        }
                    }

                var test = rawData["feed"]["entry"];
                if (test != undefined) {
                    /** @type {number} */
                    var value = 0;
                    var res = test;
                    for (; value < res["length"]; value++) {
                        var data = setFillAndStroke(res, value);
                        var stored = extend(res, value, data);
                        var r = create(res, value);
                        var obj = update(res, value);
                        var str = transform(res, value);
                        var val = success(res, value);
                        var url = parse(res, value);
                        /** @type {string} */
                        var s = "";
                            if (params["match"]("post-list")) {
                                /** @type {string} */
                                s = s + ('<li class="item-' + value + '"><a class="post-image-link" href="' + data + '">' + r + '</a><div class="post-info"><h2 class="post-title">' + stored + '</h2><div class="post-meta">' + val + "</div></div></div></li>");

                            } else {
                                if (params["match"]("related")) {
                                    /** @type {string} */
                                    s = s + ('<li class="related-item item-' + value + '"><div class="post-image-wrap"><a class="post-image-link" href="' + data + '">' + r + "</a>" + obj + '</div><h2 class="post-title">' + stored + '</h2><div class="post-meta">' + val + "</div></li>");
                                }
                            }

                        /** @type {string} */
                        name = name + s;
                    }
                    /** @type {string} */
                    name = name + "</ul>";
                } else {
                    /** @type {string} */
                    name = '<ul class="no-posts">Error: No Posts Found <i class="fa fa-frown"/></ul>';
                }
                    if (params["match"]("hot-posts")) {
                        url["html"](name)["parent"]()["addClass"]("show-hot");
                    } else {
                        url["html"](name);

                    }
            };
            $["ajax"](args);

        }
    }
    $(".show-search")["on"]("click", function() {
        $("#nav-search")["fadeIn"](250)["find"]("input")["focus"]();

    });
    $(".hide-search")["on"]("click", function() {
        $("#nav-search")["fadeOut"](250)["find"]("input")["blur"]();

    });
    $(".Label a, a.b-label")["attr"]("href", function(canCreateDiscussions, primaryReplicas) {
        return primaryReplicas["replace"](primaryReplicas, primaryReplicas + "/?&max-resuts=" + postPerPage);
    });
    $(".avatar-image-container img")["attr"]("src", function(isSlidingUp, tasks) {
        return tasks = tasks["replace"]("/s35-c/", "/s45-c/"), tasks = tasks["replace"]("//img1.blogblog.com/img/blank.gif", "https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEiShBcj7tMutktFa3RQSMuA4yxT0vUJvw6taisX3_h54B3dJLnpovpTXELFuc8ANNPgDAW7lTTtoR2-VNGO-8hjGzWhJyyQuBaVRriQU-Ar_1W-JrftEQ9_HN8Xiny4TByPp98qAgiufwv2/s55-r/avatar.png"), tasks;
    });
    $(".author-description a")["each"](function() {
        $(this)["attr"]("target", "_blank");
    });
    $(".post-nav")["each"](function() {
        var requestOrUrl = $("a.prev-post-link")["attr"]("href");
        var activeTabUrl = $("a.next-post-link")["attr"]("href");
        $["ajax"]({
            "url": requestOrUrl,
            "type": "get",
            "success": function(doc) {
                var artistTrack = $(doc)["find"](".blog-post h1.post-title")["text"]();
                $(".post-prev a .post-nav-inner p")["text"](artistTrack);
            }
        });
        $["ajax"]({
            "url": activeTabUrl,
            "type": "get",
            "success": function(stats) {
                var artistTrack = $(stats)["find"](".blog-post h1.post-title")["text"]();
                $(".post-next a .post-nav-inner p")["text"](artistTrack);

            }
        });
    });
    $(".post-body strike")["each"](function() {
        var signal = $(this);
        var htmlEntitiesMap = signal["text"]();
        if (htmlEntitiesMap["match"]("left-sidebar")) {
            signal["replaceWith"]("<style>.item #main-wrapper{float:right}.item #sidebar-wrapper{float:left}</style>");
        }
        if (htmlEntitiesMap["match"]("right-sidebar")) {
            signal["replaceWith"]("<style>.item #main-wrapper{float:left}.item #sidebar-wrapper{float:right}</style>");
        }
        if (htmlEntitiesMap["match"]("full-width")) {
            signal["replaceWith"]("<style>.item #main-wrapper{width:100%}.item #sidebar-wrapper{display:none}</style>");
        }
    });
    $("#main-wrapper, #sidebar-wrapper")["each"](function() {
        if (fixedSidebar == !![]) {
            var artistTrack = {};
            /** @type {number} */
            artistTrack["additionalMarginTop"] = 30;
            /** @type {number} */
            artistTrack["additionalMarginBottom"] = 30;

        }

    });
    $(".back-top")["each"](function() {
        var item = $(this);
        $(window)["on"]("scroll", function() {
            if ($(this)["scrollTop"]() >= 100) {
                item["fadeIn"](250);
            } else {
                item["fadeOut"](250);
            }
        });
        item["click"](function() {
            var scrollPos = {};
            /** @type {number} */
            scrollPos["scrollTop"] = 0;
            $("html, body")["animate"](scrollPos, 500);
        });

    });

    $(".common-widget .widget-content")["each"](function() {
        var dl = $(this);
        var d = dl["text"]()["trim"]();
        var where = d["toLowerCase"]();
        var pathArray = d["split"]("/");
        var icon = pathArray[0];
        var hash = pathArray[1];
        add(dl, where, icon, hash);

    });
    // LOOK THIS UP!!
    $(".related-ready")["each"](function() {
        var dl = $(this);
        var hash = dl["find"](".related-tag")["data"]("label");
        add(dl, "related", 3, hash);
    });
});
